import{_ as e,o,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Atalho para árvore no menu da minuta","description":"","frontmatter":{"title":"Atalho para árvore no menu da minuta","id":"eproc-atalho-arvore-minuta","plataforma":"eproc","grupo":"Árvore e minuta","plano":"free","desde":"1.4.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-atalho-arvore-minuta"}]]},"headers":[],"relativePath":"funcionalidades/eproc-atalho-arvore-minuta.md","filePath":"funcionalidades/eproc-atalho-arvore-minuta.md"}'),n={name:"funcionalidades/eproc-atalho-arvore-minuta.md"};function i(u,a,s,l,d,m){return o(),r("div",null,a[0]||(a[0]=[t('<h1 id="atalho-para-arvore-no-menu-da-minuta" tabindex="-1">Atalho para árvore no menu da minuta <a class="header-anchor" href="#atalho-para-arvore-no-menu-da-minuta" aria-label="Permalink to &quot;Atalho para árvore no menu da minuta&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na visualização de uma minuta, acrescenta o item <strong>Árvore</strong> ao menu flutuante, que abre a árvore de documentos do processo numa nova aba. Também transforma as menções a &quot;Evento N&quot; e &quot;Evento N, documento M&quot; no texto da minuta em links que abrem a árvore já nesse ponto.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela de visualização de minuta, no menu flutuante (junto de &quot;Alterações e Marcações&quot; e &quot;Lembretes da minuta&quot;) e no texto da própria minuta.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra uma minuta para visualização.</li><li>No menu flutuante, clique em <strong>Árvore</strong>. Na primeira vez, o item mostra &quot;Carregando em segundo plano...&quot; enquanto o eploc busca o endereço da árvore. Em seguida a árvore abre numa nova aba.</li><li>No texto da minuta, clique numa menção como &quot;Evento 4&quot; ou &quot;Evento 4, documento 1&quot;. A árvore abre rolada até o evento, com ele destacado e, se um documento foi indicado, com esse documento aberto.</li><li>Os cliques seguintes reaproveitam a mesma aba da árvore, enquanto ela estiver aberta.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar. A parte que rola e destaca o evento na árvore é feita por <a href="./eproc-arvore-focar-eventos">Focar evento/documento na árvore</a>, que acompanha este recurso.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O primeiro clique em cada página demora um pouco, porque o endereço da árvore precisa ser obtido da página do processo.</li><li>Menções que o eproc já transformou em link continuam com o link original do eproc.</li></ul>',11)]))}const h=e(n,[["render",i]]);export{p as __pageData,h as default};
